import React, { useLayoutEffect, useMemo } from 'react';
import type { HighlightPart, RecognizeDocBlock, RecognizeDocument } from './desensitizeRecognize';

type Props = {
  document: RecognizeDocument;
  fileTitle?: string;
  /** 当前定位的识别命中 */
  activeHitId?: string | null;
  /** recognize：高亮识别；masked：脱敏后预览 */
  variant?: 'recognize' | 'masked';
};

type PageBlock = {
  block: RecognizeDocBlock;
  blockIndex: number;
};

/**
 * 按文档结构切页（避免高度测量误差导致裁切/空白）：
 * 第 1 页：标题 + 当事人信息
 * 第 2 页：诉讼请求 + 事实理由 + 证据清单
 */
function splitIntoPages(blocks: RecognizeDocBlock[]): PageBlock[][] {
  if (blocks.length === 0) return [[]];

  const pages: PageBlock[][] = [[]];
  let pageIndex = 0;

  blocks.forEach((block, blockIndex) => {
    // 仅在「二、」处分页，保证正文完整、两页结构稳定
    const startNewPage =
      block.type === 'heading' &&
      /^二、/.test(block.text) &&
      pages[pageIndex].length > 0;

    if (startNewPage) {
      pages.push([]);
      pageIndex += 1;
    }
    pages[pageIndex].push({ block, blockIndex });
  });

  return pages;
}

function HighlightText({
  parts,
  activeHitId,
  variant = 'recognize',
}: {
  parts: HighlightPart[];
  activeHitId?: string | null;
  variant?: 'recognize' | 'masked';
}) {
  return (
    <>
      {parts.map((part, index) => {
        const lines = part.text.split('\n');
        return (
          <React.Fragment key={`${part.hitId || part.text}-${index}`}>
            {lines.map((line, lineIndex) => (
              <React.Fragment key={`${index}-${lineIndex}`}>
                {lineIndex > 0 ? <br /> : null}
                {part.ignored && variant === 'recognize' ? (
                  <mark
                    data-hit-id={part.hitId}
                    className={`rounded-[2px] px-0.5 font-semibold text-slate-400 line-through decoration-slate-300 transition-all duration-300 ${
                      part.hitId && activeHitId === part.hitId
                        ? 'bg-slate-100 shadow-[0_0_0_3px_rgba(148,163,184,0.35)]'
                        : 'bg-transparent'
                    }`}
                    title="已忽略，脱敏时将跳过"
                  >
                    {line}
                  </mark>
                ) : part.sensitive || part.masked ? (
                  <mark
                    data-hit-id={part.hitId}
                    className={
                      variant === 'masked' || part.masked
                        ? 'rounded-[2px] bg-[#dcfce7] px-0.5 font-semibold text-[#16a34a]'
                        : `rounded-[2px] px-0.5 font-semibold text-[#e85a2b] transition-all duration-300 ${
                            part.hitId && activeHitId === part.hitId
                              ? 'bg-[#fde8d8] shadow-[0_0_0_3px_rgba(232,90,43,0.25)]'
                              : 'bg-transparent'
                          }`
                    }
                    title={
                      variant === 'masked' || part.masked
                        ? part.fieldLabel
                          ? `已脱敏：${part.fieldLabel}`
                          : '已脱敏'
                        : part.fieldLabel
                          ? `敏感字段：${part.fieldLabel}`
                          : '敏感信息'
                    }
                  >
                    {line}
                  </mark>
                ) : (
                  line
                )}
              </React.Fragment>
            ))}
          </React.Fragment>
        );
      })}
    </>
  );
}

function DocBlockView({
  block,
  isFirstOnPage,
  activeHitId,
  variant = 'recognize',
}: {
  block: RecognizeDocBlock;
  isFirstOnPage?: boolean;
  activeHitId?: string | null;
  variant?: 'recognize' | 'masked';
}) {
  if (block.type === 'title') {
    return (
      <h1 className="mb-5 text-center text-[24px] font-extrabold tracking-wide text-slate-900">
        {block.text}
      </h1>
    );
  }

  if (block.type === 'meta') {
    return (
      <p className="mb-6 text-center text-[12px] font-medium leading-relaxed text-slate-500">
        <HighlightText parts={block.parts} activeHitId={activeHitId} variant={variant} />
      </p>
    );
  }

  if (block.type === 'heading') {
    return (
      <h2
        className={`mb-3 text-[15px] font-extrabold text-blue-700 ${isFirstOnPage ? 'mt-0' : 'mt-6'}`}
      >
        {block.text}
      </h2>
    );
  }

  if (block.type === 'paragraph') {
    return (
      <p className="mb-3 text-[13px] font-medium leading-[1.85] text-slate-800 indent-[2em]">
        <HighlightText parts={block.parts} activeHitId={activeHitId} variant={variant} />
      </p>
    );
  }

  if (block.type === 'table') {
    return (
      <div className="mb-5 overflow-hidden rounded-lg border border-slate-200">
        <table className="w-full border-collapse text-left text-[11px]">
          <thead>
            <tr className="bg-[#eef5fb]">
              {block.headers.map((header) => (
                <th
                  key={header}
                  className="border-b border-slate-200 px-2.5 py-2 font-extrabold text-slate-700"
                >
                  {header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {block.rows.map((row, rowIndex) => (
              <tr key={`row-${rowIndex}`} className="align-top odd:bg-white even:bg-slate-50/60">
                {row.map((cell, cellIndex) => (
                  <td
                    key={`cell-${rowIndex}-${cellIndex}`}
                    className="border-b border-slate-100 px-2.5 py-2.5 font-medium leading-[1.65] text-slate-700"
                  >
                    <HighlightText parts={cell} activeHitId={activeHitId} variant={variant} />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  return null;
}

/**
 * 智能脱敏识别结果：标准 A4 多页纸张预览，敏感信息橙红高亮
 */
export default function DesensitizeRecognizePreview({
  document,
  fileTitle,
  activeHitId = null,
  variant = 'recognize',
}: Props) {
  const pages = useMemo(() => splitIntoPages(document.blocks), [document.blocks]);
  const totalPages = Math.max(pages.length, 1);
  const isMasked = variant === 'masked';

  useLayoutEffect(() => {
    if (!activeHitId) return;
    const target = window.document.querySelector<HTMLElement>(
      `[data-hit-id="${activeHitId}"]`
    );
    target?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [activeHitId]);

  return (
    <div className="relative mx-auto flex w-full max-w-[210mm] shrink-0 flex-col gap-6 self-start">
      {pages.map((pageBlocks, pageIndex) => (
        <div
          key={`page-${pageIndex}`}
          className="flex w-full max-w-[210mm] shrink-0 flex-col rounded-sm border border-gray-200 bg-white px-10 py-12 shadow-md"
          style={{
            // 标准 A4：宽 210mm，高至少 297mm；内容多时允许增高，避免裁切
            width: '100%',
            maxWidth: '210mm',
            minHeight: '297mm',
          }}
        >
          {pageIndex === 0 ? (
            <div className="mb-5 flex shrink-0 items-center justify-between gap-3 border-b border-slate-100 pb-3">
              <div className="min-w-0 flex-1">
                <p
                  className="truncate text-[12px] font-bold text-slate-400"
                  title={`${fileTitle || document.title} · ${isMasked ? '脱敏结果预览' : '识别结果预览'}`}
                >
                  {fileTitle || document.title} · {isMasked ? '脱敏结果预览' : '识别结果预览'}
                </p>
                <p className={`mt-1 text-[12px] font-bold ${isMasked ? 'text-[#16a34a]' : 'text-[#e85a2b]'}`}>
                  {isMasked
                    ? `已处理敏感信息 ${document.hitCount} 处`
                    : `已标记敏感信息 ${document.hitCount} 处`}
                </p>
              </div>
              <span
                className={`shrink-0 rounded-md px-2 py-1 text-[10px] font-extrabold ${
                  isMasked
                    ? 'bg-emerald-50 text-emerald-600'
                    : 'bg-blue-50 text-blue-600'
                }`}
              >
                {isMasked ? '脱敏完成' : '识别完成'}
              </span>
            </div>
          ) : (
            <div className="mb-4 flex shrink-0 items-center justify-between gap-3 border-b border-slate-100 pb-3">
              <p
                className="min-w-0 truncate text-[11px] font-bold text-slate-400"
                title={fileTitle || document.title}
              >
                {fileTitle || document.title}
              </p>
              <span className="shrink-0 text-[10px] font-bold text-slate-400">续页</span>
            </div>
          )}

          <div className="flex-1">
            {pageBlocks.map(({ block, blockIndex }, localIndex) => (
              <DocBlockView
                key={`page-${pageIndex}-block-${blockIndex}`}
                block={block}
                isFirstOnPage={localIndex === 0}
                activeHitId={activeHitId}
                variant={variant}
              />
            ))}
          </div>

          <div className="mt-8 flex shrink-0 items-center justify-center pt-2 text-[11px] font-bold text-slate-400">
            第 {pageIndex + 1} / {totalPages} 页
          </div>
        </div>
      ))}
    </div>
  );
}
