import type { RegulatoryReviewScope } from './reviewScopes';

export type RegulatorySeverity = '高' | '中' | '低';

export type RegulatoryReviewIssue = {
  id: string;
  severity: RegulatorySeverity;
  /** 条款/命中原文 */
  clauseHit: string;
  /** 风险说明 */
  riskDetail: string;
  /** 法律依据 */
  legalBasis: string;
  /** 修改建议 */
  suggestion: string;
};

export type SuggestedClause = {
  id: string;
  title: string;
  body: string;
};

export type RegulatoryReviewMemo = {
  /** 封面主标题：制度名称 */
  documentTitle: string;
  /** 副标题 */
  subtitle: string;
  title: string;
  reviewDate: string;
  conclusion: string;
  riskSummary: string;
  reviewScope: string;
  sourceStatus: string;
  reviewNotes: string;
  overallConclusion: string;
  keyRisks: string[];
  issues: RegulatoryReviewIssue[];
  suggestedClauses: SuggestedClause[];
  pendingItems: string[];
  mainReferences: string;
  /** 兼容旧字段：纯文本摘要 */
  markdown: string;
};

type BuildMemoOptions = {
  fileTitle?: string;
  scope?: RegulatoryReviewScope;
  basisTitles?: string[];
};

