function todayLabel(): string {
  const now = new Date();
  return `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日`;
}

function countBySeverity(issues: RegulatoryReviewIssue[]) {
  return {
    high: issues.filter((i) => i.severity === '高').length,
    medium: issues.filter((i) => i.severity === '中').length,
    low: issues.filter((i) => i.severity === '低').length,
  };
}

export function countIssuesBySeverity(issues: RegulatoryReviewIssue[]) {
  return countBySeverity(issues);
}

function stripExtension(name: string): string {
  return name.replace(/\.(txt|doc|docx|pdf)$/i, '');
}

export function buildMockReviewMemo(options: BuildMemoOptions = {}): RegulatoryReviewMemo {
  const rawTitle = options.fileTitle || 'XX科技有限公司员工管理制度（测试版）';
  const documentTitle = stripExtension(rawTitle);
  const scopeName = options.scope?.name || '默认合规审查';
  const layers =
    options.scope?.layers?.join('、') ||
    '制度完整性、劳动用工、薪酬、竞业限制、知识产权、员工个人信息';
  const basisLine =
    options.basisTitles && options.basisTitles.length > 0
      ? options.basisTitles.join('、')
      : '已读取制度原文及官方公开法律文本；地方规则、内部制度及协议待核验';

  const issues = SAMPLE_ISSUES;
  const counts = countBySeverity(issues);
  const riskSummary = `高风险 ${counts.high} 项｜中风险 ${counts.medium} 项${
    counts.low > 0 ? `｜低风险 ${counts.low} 项` : ''
  }`;
  const conclusion = '需实质性重写后再发布';
  const reviewNotes =
    `已读取制度正文，并结合公开法律文本形成审查结论。审查手册：${scopeName}。` +
    '病假、医疗期、工时制审批、知识产权归属及内部民主程序，仍需结合用工地规则和企业内部材料确认。';
  const overallConclusion =
    '该制度不宜直接作为员工处分、扣薪或解除劳动合同的依据。建议先停用高风险条款，再完成专题重写、内部程序及用工地规则核验。';
  const mainReferences =
    '《劳动合同法》第4、23—25、30—31、37、39、50条；《劳动法》第41、44条；《工资支付暂行规定》第15、16条；《个人信息保护法》第6、13、17、28—30、47条。均标注为[官方来源]；地方性规则和未取得内部材料已另行标注待核验。';

  const title = `${documentTitle}合规审查备忘录`;
  const markdown =
    `${documentTitle}\n合规审查备忘录\n\n` +
    `审查结论：${conclusion}\n风险概览：${riskSummary}\n\n` +
    `【审查备注】\n${reviewNotes}\n\n` +
    `【总体结论】\n${overallConclusion}\n\n` +
    `【问题清单】共 ${issues.length} 项\n`;

  return {
    documentTitle,
    subtitle: '合规审查备忘录',
    title,
    reviewDate: todayLabel(),
    conclusion,
    riskSummary,
    reviewScope: layers,
    sourceStatus: basisLine,
    reviewNotes,
    overallConclusion,
    keyRisks: SAMPLE_KEY_RISKS,
    issues,
    suggestedClauses: SAMPLE_SUGGESTED_CLAUSES,
    pendingItems: SAMPLE_PENDING,
    mainReferences,
    markdown,
  };
}
