import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { ChevronLeft, ChevronRight, Info } from 'lucide-react';
import type { MatchConditionGroup } from './mockSearchResult';

type MatchConditionGroupBarProps = {
  groups: MatchConditionGroup[];
  activeGroupId: string;
  onSelectGroup: (groupId: string) => void;
};

function formatGroupTooltip(group: MatchConditionGroup, index: number): React.ReactNode {
  const lines: { label: string; value: string }[] = [];
  const title = `条件组${index + 1}：${group.name}`;
  lines.push({ label: '', value: title });

  const s = group.summary;
  if (s.intent) lines.push({ label: '检索意图', value: s.intent });
  if (s.keywords?.length) lines.push({ label: '关键词', value: s.keywords.join('、') });
  if (s.lawScope) lines.push({ label: '法规范围', value: s.lawScope });
  if (s.region) lines.push({ label: '地域', value: s.region });
  if (s.timeliness) lines.push({ label: '时效状态', value: s.timeliness });
  if (s.effectiveness?.length) {
    lines.push({ label: '效力层级', value: s.effectiveness.join('、') });
  }
  lines.push({ label: '召回结果', value: `${group.count} 条` });

  return (
    <div className="space-y-1.5 text-[11px] leading-relaxed">
      {lines.map((line, i) =>
        line.label ? (
          <p key={i} className="text-slate-600">
            <span className="font-bold text-slate-700">{line.label}：</span>
            {line.value}
          </p>
        ) : (
          <p key={i} className="font-extrabold text-slate-900">{line.value}</p>
        )
      )}
    </div>
  );
}

const SCROLL_ARROW_GRADIENT_CLASS =
  'absolute top-0 bottom-0 z-10 flex w-10 items-center transition-opacity';

const MatchConditionGroupBar: React.FC<MatchConditionGroupBarProps> = ({
  groups,
  activeGroupId,
  onSelectGroup,
}) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const chipRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);
  const [hoveredGroupId, setHoveredGroupId] = useState<string | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ top: 0, left: 0 });

  const hoveredGroup = groups.find((g) => g.id === hoveredGroupId);
  const hoveredIndex = hoveredGroup ? groups.findIndex((g) => g.id === hoveredGroup.id) : -1;

  const updateScrollState = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    setCanScrollLeft(el.scrollLeft > 2);
    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 2);
  }, []);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    updateScrollState();
    const ro = new ResizeObserver(updateScrollState);
    ro.observe(el);
    return () => ro.disconnect();
  }, [groups, updateScrollState]);

  const scrollBy = (delta: number) => {
    scrollRef.current?.scrollBy({ left: delta, behavior: 'smooth' });
  };

  const updateTooltipPosition = (groupId: string) => {
    const el = chipRefs.current[groupId];
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const tooltipWidth = 320;
    const left = Math.min(rect.left, window.innerWidth - tooltipWidth - 16);
    setTooltipPos({ top: rect.bottom + 8, left: Math.max(16, left) });
  };

  const handleChipMouseEnter = (groupId: string) => {
    updateTooltipPosition(groupId);
    setHoveredGroupId(groupId);
  };

  const handleChipMouseLeave = () => {
    setHoveredGroupId(null);
  };

  if (groups.length === 0) return null;

  return (
    <div className="border-b border-slate-50 px-3 py-2">
      <div className="relative min-w-0">
        <div
          ref={scrollRef}
          onScroll={updateScrollState}
          className="overflow-x-auto [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          <div className="flex gap-2 py-0.5">
            {groups.map((group, index) => {
              const active = group.id === activeGroupId;
              return (
                <button
                  key={group.id}
                  ref={(el) => {
                    chipRefs.current[group.id] = el;
                  }}
                  type="button"
                  onClick={() => onSelectGroup(group.id)}
                  onMouseEnter={() => handleChipMouseEnter(group.id)}
                  onMouseLeave={handleChipMouseLeave}
                  className={`inline-flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-1.5 text-[12px] font-extrabold transition ${
                    active
                      ? 'border border-blue-400 bg-blue-50 text-blue-700'
                      : 'bg-slate-100 text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                  }`}
                >
                  <span>
                    条件组{index + 1}：{group.name}
                  </span>
                  <span className="tabular-nums text-[11px] font-bold opacity-90">
                    {group.count}
                  </span>
                  <Info
                    size={13}
                    strokeWidth={2.25}
                    className={`shrink-0 opacity-70 ${active ? 'text-blue-600' : 'text-slate-400'}`}
                    aria-hidden
                  />
                </button>
              );
            })}
          </div>
        </div>

        {canScrollLeft ? (
          <button
            type="button"
            onClick={() => scrollBy(-180)}
            className={`${SCROLL_ARROW_GRADIENT_CLASS} left-0 justify-start pl-0.5 bg-gradient-to-r from-white from-20% via-white/75 to-transparent text-slate-400 hover:text-slate-600`}
            aria-label="向左滚动条件组"
          >
            <ChevronLeft size={18} strokeWidth={2} />
          </button>
        ) : null}

        {canScrollRight ? (
          <button
            type="button"
            onClick={() => scrollBy(180)}
            className={`${SCROLL_ARROW_GRADIENT_CLASS} right-0 justify-end pr-0.5 bg-gradient-to-l from-white from-20% via-white/75 to-transparent text-slate-400 hover:text-slate-600`}
            aria-label="向右滚动条件组"
          >
            <ChevronRight size={18} strokeWidth={2} />
          </button>
        ) : null}
      </div>

      {hoveredGroup && hoveredIndex >= 0
        ? createPortal(
            <div
              className="pointer-events-none fixed z-[2000] w-[min(320px,calc(100vw-32px))] rounded-xl border border-slate-200/90 bg-white p-3 shadow-lg shadow-slate-200/80"
              style={{ top: tooltipPos.top, left: tooltipPos.left }}
              role="tooltip"
            >
              {formatGroupTooltip(hoveredGroup, hoveredIndex)}
            </div>,
            document.body
          )
        : null}
    </div>
  );
};

export default MatchConditionGroupBar;
