import React, { useEffect, useRef, useState } from 'react';
import { ChevronDown, ChevronRight } from 'lucide-react';
import {
  formatModelDisplay,
  LEGACY_MODELS,
  type ModelOption,
  PRIMARY_MODELS,
  supportsThinkingMode,
} from './modelConfig';

interface ModelSelectorProps {
  modelId: string;
  onModelChange: (id: string) => void;
  thinkingEnabled: boolean;
  onThinkingChange: (enabled: boolean) => void;
}

const ModelRow: React.FC<{
  option: ModelOption;
  selected: boolean;
  onSelect: () => void;
}> = ({ option, selected, onSelect }) => (
  <button
    type="button"
    role="menuitemradio"
    aria-checked={selected}
    onClick={onSelect}
    className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left transition ${
      selected ? 'bg-blue-50' : 'hover:bg-slate-50'
    }`}
  >
    <div className="min-w-0 flex-1">
      <div className="text-[13px] font-bold text-slate-800">{option.label}</div>
      {option.description ? (
        <p className="mt-0.5 text-[11px] font-medium text-slate-500">{option.description}</p>
      ) : null}
    </div>
    {option.highCost ? (
      <span className="shrink-0 rounded-md bg-amber-50 px-1.5 py-0.5 text-[10px] font-bold leading-none text-amber-700 ring-1 ring-inset ring-amber-200/80">
        高消耗
      </span>
    ) : null}
  </button>
);

const ModelSelector: React.FC<ModelSelectorProps> = ({
  modelId,
  onModelChange,
  thinkingEnabled,
  onThinkingChange,
}) => {
  const [open, setOpen] = useState(false);
  const [legacyExpanded, setLegacyExpanded] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  const thinkingAvailable = supportsThinkingMode(modelId);
  const legacySelected = LEGACY_MODELS.some((m) => m.id === modelId);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open]);

  useEffect(() => {
    if (open && legacySelected) setLegacyExpanded(true);
  }, [open, legacySelected]);

  const selectModel = (id: string) => {
    onModelChange(id);
    setOpen(false);
  };

  const triggerLabel = formatModelDisplay(modelId, thinkingEnabled);

  return (
    <div ref={rootRef} className="relative shrink-0">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-label="选择模型"
        className="flex cursor-pointer items-center gap-1.5 rounded-lg border border-slate-200 bg-slate-50 py-1.5 pl-3 pr-2.5 text-[12px] font-bold text-slate-700 outline-none transition hover:border-slate-300"
      >
        <span className="max-w-[180px] truncate">{triggerLabel}</span>
        <ChevronDown
          className={`h-3.5 w-3.5 shrink-0 text-slate-400 transition ${open ? 'rotate-180' : ''}`}
          aria-hidden
        />
      </button>

      {open ? (
        <div
          role="listbox"
          aria-label="模型列表"
          className="absolute left-0 top-[calc(100%+6px)] z-50 w-[min(300px,calc(100vw-2rem))] overflow-hidden rounded-xl border border-slate-200/90 bg-white py-1.5 shadow-lg shadow-slate-200/80"
        >
          <div className="px-1">
            {PRIMARY_MODELS.map((option) => (
              <ModelRow
                key={option.id}
                option={option}
                selected={modelId === option.id}
                onSelect={() => selectModel(option.id)}
              />
            ))}

            <div className="my-1 border-t border-slate-100" />

            <button
              type="button"
              onClick={() => setLegacyExpanded((v) => !v)}
              className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-[13px] font-bold text-slate-700 transition hover:bg-slate-50"
              aria-expanded={legacyExpanded}
            >
              <span className="flex-1">其他模型</span>
              {legacyExpanded ? (
                <ChevronDown className="h-4 w-4 text-slate-400" aria-hidden />
              ) : (
                <ChevronRight className="h-4 w-4 text-slate-400" aria-hidden />
              )}
            </button>

            {legacyExpanded ? (
              <div className="pb-0.5 pl-1">
                {LEGACY_MODELS.map((option) => (
                  <ModelRow
                    key={option.id}
                    option={option}
                    selected={modelId === option.id}
                    onSelect={() => selectModel(option.id)}
                  />
                ))}
              </div>
            ) : null}
          </div>

          <div className="mx-3 my-1.5 border-t border-slate-100" />

          <div
            className={`flex items-center gap-3 px-3 py-2.5 ${
              thinkingAvailable ? '' : 'opacity-50'
            }`}
          >
            <div className="min-w-0 flex-1">
              <p className="text-[13px] font-bold text-slate-800">思考模式</p>
              <p className="mt-0.5 text-[11px] font-medium text-slate-500">
                {thinkingAvailable ? '思考更充分，回答更优质' : '当前模型暂不支持思考模式'}
              </p>
            </div>
            <button
              type="button"
              role="switch"
              aria-checked={thinkingEnabled && thinkingAvailable}
              aria-label="思考模式"
              disabled={!thinkingAvailable}
              onClick={() => thinkingAvailable && onThinkingChange(!thinkingEnabled)}
              className={`relative h-6 w-11 shrink-0 rounded-full transition ${
                thinkingEnabled && thinkingAvailable ? 'bg-blue-600' : 'bg-slate-200'
              } ${!thinkingAvailable ? 'cursor-not-allowed' : 'cursor-pointer'}`}
            >
              <span
                className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition ${
                  thinkingEnabled && thinkingAvailable ? 'left-[22px]' : 'left-0.5'
                }`}
              />
            </button>
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default ModelSelector;
