export type ModelTier = 'v4' | 'legacy';

export interface ModelOption {
  id: string;
  label: string;
  description?: string;
  tier: ModelTier;
  /** 价格偏高，选择器右侧展示「高消耗」提示 */
  highCost?: boolean;
}

export const PRIMARY_MODELS: ModelOption[] = [
  {
    id: 'DeepSeek-V4-Flash',
    label: 'DeepSeek-V4-Flash',
    description: '极速响应，兼顾性能和性价比（最新）',
    tier: 'v4',
  },
  {
    id: 'DeepSeek-V4-Pro',
    label: 'DeepSeek-V4-Pro',
    description: '深度逻辑推演，处理复杂法律疑难（最新）',
    tier: 'v4',
  },
];

/** 默认收起的「其他模型」 */
export const LEGACY_MODELS: ModelOption[] = [
  { id: 'GPT-5.6-Luna', label: 'GPT-5.6-Luna', tier: 'legacy', highCost: true },
  { id: 'Kimi-K3', label: 'Kimi-K3', tier: 'legacy', highCost: true },
];

export const ALL_MODELS = [...PRIMARY_MODELS, ...LEGACY_MODELS];

export function isV4Model(modelId: string): boolean {
  return PRIMARY_MODELS.some((m) => m.id === modelId);
}

/** 当前上架模型均支持思考模式（含其他模型中的高消耗模型） */
export function supportsThinkingMode(modelId: string): boolean {
  return ALL_MODELS.some((m) => m.id === modelId);
}

export function getModelLabel(modelId: string): string {
  return ALL_MODELS.find((m) => m.id === modelId)?.label ?? modelId;
}

export function formatModelDisplay(modelId: string, thinkingEnabled: boolean): string {
  const label = getModelLabel(modelId);
  if (supportsThinkingMode(modelId) && thinkingEnabled) return `${label} · 思考`;
  return label;
}
