const NAV_SUBMENU_CLOSE_DELAY_MS = 180;

const NavItemWithSubmenu = ({
  icon,
  label,
  active,
  activeSubId,
  items,
  onSelectItem,
  menuMinWidthClass = 'min-w-[168px]',
}) => {
  const triggerRef = useRef(null);
  const flyoutRef = useRef(null);
  const closeTimerRef = useRef(null);
  const [displayMode, setDisplayMode] = useState('hover');
  const [hoverOpen, setHoverOpen] = useState(false);
  const [flyoutStyle, setFlyoutStyle] = useState({ top: 0, left: 0 });

  const isAccordionMode = displayMode === 'accordion';

  const clearCloseTimer = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  /** 估算二级菜单高度（仅首次展开、尚未渲染时用） */
  const estimateFlyoutHeight = () => Math.max(items.length, 1) * 36 + 12;

  /**
   * 定位二级菜单：
   * - 下方空间足够时，顶对齐一级菜单
   * - 下方不足时，二级菜单底部贴齐视口底部
   */
  const updateFlyoutPosition = (measuredHeight) => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    const viewportH = window.innerHeight;
    const margin = 8;
    // 优先用实测高度，避免估算值与真实高度不一致导致跳动
    const menuHeight =
      measuredHeight || flyoutRef.current?.offsetHeight || estimateFlyoutHeight();
    const left = rect.right - 6;

    // 默认：与一级项顶部对齐
    let top = rect.top;
    const spaceBelow = viewportH - rect.top - margin;

    if (spaceBelow < menuHeight) {
      // 下方不足：贴齐视口底部
      top = viewportH - menuHeight - margin;
    }

    // 极端矮屏时避免顶部溢出
    top = Math.max(margin, top);

    setFlyoutStyle({ top, left });
  };

  const handleTriggerMouseEnter = () => {
    if (isAccordionMode) return;
    clearCloseTimer();
    // 仅在首次打开时用估算预定位；已打开则不动位置，交给实测精修
    if (!hoverOpen) {
      updateFlyoutPosition();
      setHoverOpen(true);
    }
  };

  /** 移入二级菜单时只取消关闭，不再用估算高度重算位置（否则会跳动） */
  const handleFlyoutMouseEnter = () => {
    if (isAccordionMode) return;
    clearCloseTimer();
  };

  const handleMouseLeave = () => {
    if (isAccordionMode) return;
    clearCloseTimer();
    closeTimerRef.current = setTimeout(() => setHoverOpen(false), NAV_SUBMENU_CLOSE_DELAY_MS);
  };

  useEffect(() => () => clearCloseTimer(), []);

  // 展开后用真实高度精修位置；窗口变化时同步更新
  useLayoutEffect(() => {
    if (!hoverOpen || isAccordionMode) return;

    const refine = () => {
      const h = flyoutRef.current?.offsetHeight;
      updateFlyoutPosition(h);
    };

    refine();
    window.addEventListener('resize', refine);
    window.addEventListener('scroll', refine, true);
    return () => {
      window.removeEventListener('resize', refine);
      window.removeEventListener('scroll', refine, true);
    };
  }, [hoverOpen, isAccordionMode, items.length]);

  const handleParentClick = () => {
    if (isAccordionMode) {
      setDisplayMode('hover');
      return;
    }
    setHoverOpen(false);
    clearCloseTimer();
    setDisplayMode('accordion');
  };

  const handleSelectSubItem = (id) => {
    onSelectItem(id);
  };

  const renderSubItems = (variant) =>
    items.map((item) => {
      const isActive = activeSubId === item.id;
      const isInline = variant === 'inline';
      return (
        <button
          key={item.id}
          type="button"
          onClick={() => handleSelectSubItem(item.id)}
          className={
            isInline
              ? `flex w-full min-w-0 items-center gap-2 rounded-lg py-2 pl-7 pr-2 text-left text-[12px] font-bold transition ${
                  isActive
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-slate-700 hover:bg-slate-50'
                }`
              : `flex w-full items-center gap-2 px-3 py-2 text-left text-[12px] font-bold transition ${
                  isActive
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-slate-700 hover:bg-slate-50'
                }`
          }
        >
          {item.icon ? (
            <span className={`shrink-0 ${isActive ? 'text-blue-600' : 'text-slate-500'}`}>
              {item.icon}
            </span>
          ) : null}
          <span className="min-w-0 truncate whitespace-nowrap">{item.label}</span>
        </button>
      );
    });

  return (
    <>
      <div
        ref={triggerRef}
        className="relative"
        onMouseEnter={handleTriggerMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <button
          type="button"
          onClick={handleParentClick}
          aria-expanded={isAccordionMode || hoverOpen}
          className={`flex w-full min-w-0 items-center gap-2 rounded-lg px-2 py-2.5 font-bold transition-all ${
            isAccordionMode
              ? 'bg-slate-100 text-slate-800'
              : active
                ? 'bg-blue-50 text-blue-600 shadow-sm'
                : 'text-gray-600 hover:bg-gray-100'
          }`}
        >
          <span
            className={`shrink-0 ${
              isAccordionMode ? 'text-slate-600' : active ? 'text-blue-600' : 'text-gray-400'
            }`}
          >
            {icon}
          </span>
          <span className="min-w-0 flex-1 truncate text-left text-[12px] whitespace-nowrap">{label}</span>
          {isAccordionMode ? (
            <ChevronDown size={14} className="ml-auto shrink-0 text-slate-500" aria-hidden />
          ) : (
            <ChevronRight
              size={14}
              className={`ml-auto shrink-0 ${active ? 'text-blue-400' : 'text-gray-300'}`}
              aria-hidden
            />
          )}
        </button>

        {isAccordionMode ? (
          <div className="mt-0.5 space-y-0.5">{renderSubItems('inline')}</div>
        ) : null}
      </div>

      {!isAccordionMode && hoverOpen ? (
        <div
          ref={flyoutRef}
          className="fixed z-[120] pl-1.5"
          style={{ top: flyoutStyle.top, left: flyoutStyle.left }}
          onMouseEnter={handleFlyoutMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          <div
            className={`${menuMinWidthClass} rounded-xl border border-slate-200/90 bg-white py-1.5 shadow-[0_8px_24px_rgba(15,23,42,0.12)]`}
          >
            {renderSubItems('flyout')}
          </div>
        </div>
      ) : null}
    </>
  );
};

