/** 案号、条号、法规引用等与表格视图一致的浅底圆角高亮 */
const LEGAL_ENTITY_HIGHLIGHT_CLASS =
  'inline rounded px-1.5 py-0.5 bg-sky-100/95 text-slate-800 font-medium [box-decoration-break:clone]';

const POPOVER_GAP_PX = 8;

/** 法规/来源浮层：挂到 body + fixed，避免被聊天区 overflow 裁剪；默认向下，空间不足向上 */
const LegalPopoverPanel = ({ open, anchorRef, widthClassName, children }) => {
  const popRef = useRef(null);
  const [placement, setPlacement] = useState('below');
  const [coords, setCoords] = useState(null);

  useLayoutEffect(() => {
    if (!open) {
      setCoords(null);
      return;
    }
    const update = () => {
      const anchor = anchorRef?.current;
      if (!anchor) return;
      const pop = popRef.current;
      const rect = anchor.getBoundingClientRect();
      const estW = Math.min(360, window.innerWidth - 32);
      const h = pop?.offsetHeight ?? 300;
      const w = pop?.offsetWidth ?? estW;
      const spaceBelow = window.innerHeight - rect.bottom - POPOVER_GAP_PX;
      const spaceAbove = rect.top - POPOVER_GAP_PX;
      let next = 'below';
      if (spaceBelow >= h) next = 'below';
      else if (spaceAbove >= h) next = 'above';
      else next = spaceBelow >= spaceAbove ? 'below' : 'above';
      setPlacement(next);
      let top = next === 'below' ? rect.bottom + POPOVER_GAP_PX : rect.top - POPOVER_GAP_PX - h;
      let left = rect.left + rect.width / 2 - w / 2;
      const margin = 8;
      left = Math.max(margin, Math.min(left, window.innerWidth - w - margin));
      top = Math.max(margin, Math.min(top, window.innerHeight - h - margin));
      setCoords({ top, left });
    };
    update();
    const id = requestAnimationFrame(update);
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => {
      cancelAnimationFrame(id);
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, true);
    };
  }, [open, anchorRef, children]);

  if (!open || coords === null) return null;

  const panel = (
    <div
      ref={popRef}
      style={{ top: coords.top, left: coords.left }}
      className={`fixed max-w-[calc(100vw-1rem)] bg-white border border-slate-100 rounded-2xl shadow-2xl p-4 text-left font-normal animate-in fade-in zoom-in-95 cursor-default z-[2147483647] ${widthClassName}`}
      onClick={e => e.stopPropagation()}
    >
      {children}
      {placement === 'below' ? (
        <div className="pointer-events-none absolute -top-1.5 left-1/2 -translate-x-1/2 w-3 h-3 bg-white border-t border-l border-slate-100 rotate-45 rounded-sm" />
      ) : (
        <div className="pointer-events-none absolute -bottom-1.5 left-1/2 -translate-x-1/2 w-3 h-3 bg-white border-b border-r border-slate-100 rotate-45 rounded-sm" />
      )}
    </div>
  );

  return createPortal(panel, document.body);
};

