/** ```law 围栏：首行 lawKey|条号，其余行为展示标题；行内高亮，悬浮查看详情 */
const LawFenceInline = ({ raw }) => {
  const [show, setShow] = useState(false);
  const anchorRef = useRef(null);
  const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length === 0) return null;
  const [metaLine, ...titleLines] = lines;
  const [lawKey, artStr] = metaLine.split('|');
  const articleNum = artStr ? parseInt(artStr, 10) : null;
  const law = MOCK_LEGAL_REFERENCES[lawKey];
  const subtitle = titleLines.join(' ');
  if (!law) {
    return (
      <span className={`${LEGAL_ENTITY_HIGHLIGHT_CLASS} text-rose-800 bg-rose-100/90`}>
        {raw}
      </span>
    );
  }
  const label =
    subtitle ||
    (articleNum != null ? `${law.shortName}${law.articleLabel(articleNum)}` : law.shortName);
  return (
    <span
      ref={anchorRef}
      className="relative inline align-baseline mx-0.5"
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
    >
      <span className={`${LEGAL_ENTITY_HIGHLIGHT_CLASS} cursor-default`}>{label}</span>
      <LegalPopoverPanel open={show} anchorRef={anchorRef} widthClassName="w-[min(360px,calc(100vw-2rem))]">
        <LegalHoverCard law={law} articleNum={articleNum} />
      </LegalPopoverPanel>
    </span>
  );
};

