/** 案号：（2022）苏0891民初3865号 等，半角/全角括号 */
const CASE_NUMBER_INLINE_RE = /[（(]\d{4}[)）][^（）()\n]{0,56}?\d+号/g;

/** 《法规名 … 现行有效 》后接 第n条、第m条（允许空格） */
const LAW_BOOK_INLINE_RE =
  /《\s*([^》]+?)\s*》(?:\s*((?:第\s*\d+\s*条(?:\s*[、，,]\s*第\s*\d+\s*条)*)))?/g;

const parseBookInnerForHighlight = (inner) => {
  const t = inner.trim();
  const mm = t.match(/^(.+?)\s+现行有效\s*$/);
  if (mm) return { title: mm[1].trim(), showBadge: true };
  return { title: t, showBadge: false };
};

/** 在纯文本中识别案号、《法规》及条号并高亮（与角标/加粗语法无关的展示层） */
const renderLawBookInlineHighlights = (text, keyPrefix) => {
  const nodes = [];
  let last = 0;
  let m;
  let lawRe = new RegExp(LAW_BOOK_INLINE_RE.source, 'g');
  let idx = 0;
  while ((m = lawRe.exec(text)) !== null) {
    if (m.index > last) {
      nodes.push(
        <React.Fragment key={`${keyPrefix}-p-${idx++}`}>{text.slice(last, m.index)}</React.Fragment>
      );
    }
    const inner = m[1];
    const articleChunk = m[2];
    const { title, showBadge } = parseBookInnerForHighlight(inner);
    const resolvedLawKey = resolveLawKeyFromBookTitle(title);
    const hasTitleHover = Boolean(resolvedLawKey && !articleChunk && MOCK_LEGAL_REFERENCES[resolvedLawKey]);
    nodes.push(
      <span key={`${keyPrefix}-bk-${m.index}`} className="inline-flex flex-wrap items-baseline gap-x-1 gap-y-0.5 align-baseline mx-0.5">
        {hasTitleHover ? (
          <LawBookTitleInline lawKey={resolvedLawKey} title={title} />
        ) : (
          <span className="text-blue-600 font-semibold">《{title}》</span>
        )}
        {showBadge && (
          <span className="text-[10px] leading-none px-1.5 py-0.5 rounded-md bg-sky-100 text-sky-900 border border-sky-200/80 font-bold whitespace-nowrap">
            现行有效
          </span>
        )}
      </span>
    );
    if (articleChunk) {
      const artParts = articleChunk.split(/[、，,]\s*/).filter(Boolean);
      artParts.forEach((ap, pi) => {
        if (pi > 0) {
          nodes.push(
            <span key={`${keyPrefix}-asp-${m.index}-${pi}`} className="text-slate-600 font-medium">
              、
            </span>
          );
        }
        const apTrim = ap.trim();
        nodes.push(
          <LawArticleInline
            key={`${keyPrefix}-ar-${m.index}-${pi}`}
            lawKey={resolvedLawKey}
            articleNum={parseArticleNumFromLabel(apTrim)}
            label={apTrim}
          />
        );
      });
    }
    last = m.lastIndex;
  }
  if (last < text.length) {
    nodes.push(<React.Fragment key={`${keyPrefix}-tail-${idx}`}>{text.slice(last)}</React.Fragment>);
  }
  return nodes.length ? nodes : [<React.Fragment key={`${keyPrefix}-empty`}>{text}</React.Fragment>];
};

const renderLegalInlineHighlights = (text, keyPrefix) => {
  if (!text) return [];
  const out = [];
  let last = 0;
  let m;
  const re = new RegExp(CASE_NUMBER_INLINE_RE.source, 'g');
  let idx = 0;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) {
      out.push(...renderLawBookInlineHighlights(text.slice(last, m.index), `${keyPrefix}-lb-${idx}`));
    }
    out.push(
      <span key={`${keyPrefix}-cn-${m.index}`} className={LEGAL_ENTITY_HIGHLIGHT_CLASS}>
        {m[0]}
      </span>
    );
    last = m.lastIndex;
    idx += 1;
  }
  if (last < text.length) {
    out.push(...renderLawBookInlineHighlights(text.slice(last), `${keyPrefix}-lb-end`));
  }
  return out.length ? out : [<React.Fragment key={`${keyPrefix}-all`}>{text}</React.Fragment>];
};

const splitLawInlineSegments = (text) => {
  const segments = [];
  const re = /\{\{law:([a-zA-Z0-9_]+)(?::(\d+))?\}\}/g;
  let last = 0;
  let m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) segments.push({ type: 'text', text: text.slice(last, m.index) });
    segments.push({
      type: 'law',
      lawKey: m[1],
      articleNum: m[2] ? parseInt(m[2], 10) : null,
    });
    last = re.lastIndex;
  }
  if (last < text.length) segments.push({ type: 'text', text: text.slice(last) });
  if (segments.length === 0) segments.push({ type: 'text', text });
  return segments;
};

/** 仅处理 [[角标]] 与 **加粗** */
const parseRefAndBold = (text, sources, onBadgeClick, keyPrefix) => {
  const refParts = text.split(/\[\[(\d+)\]\]/g);
  return refParts.map((part, i) => {
    if (i % 2 === 1) {
      return <ReferenceBadge key={`${keyPrefix}-ref-${i}`} sourceId={part} sources={sources} onBadgeClick={onBadgeClick} />;
    }
    const boldParts = part.split(/\*\*(.*?)\*\*/g);
    return boldParts.map((bPart, j) => {
      if (j % 2 === 1) {
        return <strong key={`${keyPrefix}-bold-${i}-${j}`} className="font-extrabold text-slate-900">{bPart}</strong>;
      }
      return (
        <React.Fragment key={`${keyPrefix}-txt-${i}-${j}`}>
          {renderLegalInlineHighlights(bPart, `${keyPrefix}-hi-${i}-${j}`)}
        </React.Fragment>
      );
    });
  });
};

const parseInlineWithLaw = (text, sources, onBadgeClick, keyPrefix = 'il') => {
  return splitLawInlineSegments(text).map((seg, idx) => {
    if (seg.type === 'law') {
      return <LegalCitationChip key={`${keyPrefix}-law-${idx}`} lawKey={seg.lawKey} articleNum={seg.articleNum} />;
    }
    return <React.Fragment key={`${keyPrefix}-seg-${idx}`}>{parseRefAndBold(seg.text, sources, onBadgeClick, `${keyPrefix}-${idx}`)}</React.Fragment>;
  });
};

/** Markdown 叶子结点再跑法规/角标解析，使 ## 与《》高亮共存 */
/** 保证标题前有空行，避免被解析进上一段导致与正文挤在同一行 */
const normalizeChatMarkdown = (src) => {
  if (!src) return src;
  let s = src.replace(/\r\n/g, '\n');
  s = s.replace(/([^\n#])\n(#{1,6}\s)/g, '$1\n\n$2');
  s = s.replace(/([。！？…])\n(#{1,6}\s)/g, '$1\n\n$2');
  return s;
};

const enrichMarkdownChildren = (children, sources, onBadgeClick, keyPrefix = 'md') => {
  if (children == null || children === false) return null;
  return React.Children.map(children, (child, i) => {
    const k = `${keyPrefix}-${i}`;
    if (child == null || child === false) return null;
    if (typeof child === 'string') {
      return <React.Fragment key={k}>{parseInlineWithLaw(child, sources, onBadgeClick, k)}</React.Fragment>;
    }
    if (typeof child === 'number') {
      return <React.Fragment key={k}>{parseInlineWithLaw(String(child), sources, onBadgeClick, k)}</React.Fragment>;
    }
    if (React.isValidElement(child)) {
      const nested = child.props.children;
      if (nested === undefined || nested === null) {
        return React.cloneElement(child, { key: child.key ?? k });
      }
      return React.cloneElement(child, {
        key: child.key ?? k,
        children: enrichMarkdownChildren(nested, sources, onBadgeClick, `${k}-c`),
      });
    }
    return child;
  });
};

const MessageMarkdown = ({ content, sources, onBadgeClick }) => {
  const mdSource = useMemo(() => normalizeChatMarkdown(content), [content]);
  const components = useMemo(
    () => ({
      h2: ({ children }) => (
        <h2 className="block w-full text-[16px] font-extrabold text-slate-900 mt-4 mb-1.5 first:mt-0 border-b border-slate-100/90 pb-1.5 leading-snug">
          {enrichMarkdownChildren(children, sources, onBadgeClick, 'h2')}
        </h2>
      ),
      h3: ({ children }) => (
        <h3 className="block w-full text-[15px] font-extrabold text-slate-900 mt-3 mb-1 first:mt-0 leading-snug">
          {enrichMarkdownChildren(children, sources, onBadgeClick, 'h3')}
        </h3>
      ),
      h4: ({ children }) => (
        <h4 className="block w-full text-[14px] font-bold text-slate-800 mt-2.5 mb-1 first:mt-0 leading-snug">
          {enrichMarkdownChildren(children, sources, onBadgeClick, 'h4')}
        </h4>
      ),
      p: ({ children }) => (
        <p className="mb-2 last:mb-0 leading-[1.75] break-words">{enrichMarkdownChildren(children, sources, onBadgeClick, 'p')}</p>
      ),
      ul: ({ children }) => (
        <ul className="list-outside list-disc pl-5 mb-2 space-y-1 marker:text-slate-400 [padding-inline-start:1.15rem]">{children}</ul>
      ),
      ol: ({ children }) => (
        <ol className="list-outside list-decimal pl-5 mb-2 space-y-1 marker:text-slate-600 [padding-inline-start:1.15rem]">{children}</ol>
      ),
      li: ({ children }) => (
        <li className="leading-[1.75] break-words [&>p]:mb-1 [&>p]:last:mb-0">{enrichMarkdownChildren(children, sources, onBadgeClick, 'li')}</li>
      ),
      strong: ({ children }) => (
        <strong className="font-extrabold text-slate-900">{enrichMarkdownChildren(children, sources, onBadgeClick, 'st')}</strong>
      ),
      blockquote: ({ children }) => (
        <blockquote className="border-l-4 border-indigo-100 pl-3 my-2 text-slate-600 bg-slate-50/80 py-1.5 pr-2 rounded-r-lg">
          {enrichMarkdownChildren(children, sources, onBadgeClick, 'bq')}
        </blockquote>
      ),
      hr: () => <hr className="my-4 border-slate-200" />,
    }),
    [sources, onBadgeClick]
  );

  return (
    <div className="markdown-chat text-slate-800 whitespace-normal [word-break:break-word]">
      <ReactMarkdown components={components}>{mdSource}</ReactMarkdown>
    </div>
  );
};

// ==== 引用角标与悬浮预览组件 ====
