/** 原型：模拟从 SKILL.md YAML frontmatter 读取 name / description（展示名，非 zip 文件名） */
const extractSkillMetaFromZipName = (fileName = '') => {
  const base = fileName.replace(/\.zip$/i, '').trim().toLowerCase();
  // 原型按常见技能包命名映射到 YAML name；真实链路由服务端解析 SKILL.md
  if (base.includes('contract') || base.includes('合同')) {
    return {
      name: '合同审查',
      desc: '识别合同风险并生成审查建议，支持审查手册与红线批注。',
    };
  }
  if (base.includes('desensit') || base.includes('脱敏')) {
    return {
      name: '智能脱敏',
      desc: '识别并脱敏文档中的敏感信息，支持规则配置与结果核对。',
    };
  }
  // 其余包：去掉版本/时间戳尾巴，转成可读短名（仍模拟 YAML 提取结果）
  const cleaned = base
    .replace(/[-_]?(v?\d{8,}.*)$/i, '')
    .replace(/[-_]?(deepagent|agent|skill)s?/g, '')
    .replace(/[-_]+/g, ' ')
    .trim();
  const skillName = cleaned
    ? cleaned.replace(/\b\w/g, c => c.toUpperCase())
    : '未命名技能';
  return {
    name: skillName,
    desc: `基于 SKILL.md 解析的「${skillName}」技能，用于在工作空间中按指引完成对应任务。`,
  };
};

/** 搜索关键词高亮：按 query 拆分文本，匹配段以 mark 样式展示 */
const highlightSearchMatch = (text = '', query = '') => {
  const source = String(text);
  const q = query.trim();
  if (!source || !q) return source;
  const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const parts = source.split(new RegExp(`(${escaped})`, 'gi'));
  return parts.map((part, index) =>
    part.toLowerCase() === q.toLowerCase() ? (
      <mark key={`${part}-${index}`} className="bg-amber-100 text-amber-700 rounded px-0.5 font-inherit">
        {part}
      </mark>
    ) : (
      <React.Fragment key={`${part}-${index}`}>{part}</React.Fragment>
    )
  );
};

const UploadSkillModal = ({ onClose, onComplete }) => {
  const [step, setStep] = useState(1);
  const [file, setFile] = useState(null);
  const [name, setName] = useState('');
  const [desc, setDesc] = useState('');
  const [error, setError] = useState('');
  // scanning → parsing → done
  const [analyzePhase, setAnalyzePhase] = useState('idle');
  const fileInputRef = useRef(null);

  const selectFile = (nextFile) => {
    if (!nextFile) return;
    if (!nextFile.name.toLowerCase().endsWith('.zip')) {
      setFile(null);
      setError('仅支持上传 zip 文件');
      return;
    }
    setFile(nextFile);
    setName('');
    setDesc('');
    setAnalyzePhase('idle');
    setError('');
  };

  const goToStep2 = () => {
    if (!file) return;
    setError('');
    setName('');
    setDesc('');
    setAnalyzePhase('scanning');
    setStep(2);
  };

  const goBackToStep1 = () => {
    setAnalyzePhase('idle');
    setError('');
    setStep(1);
  };

  useEffect(() => {
    if (step !== 2 || analyzePhase !== 'scanning' || !file) return undefined;
    const timer = setTimeout(() => setAnalyzePhase('parsing'), 2200);
    return () => clearTimeout(timer);
  }, [step, analyzePhase, file]);

  useEffect(() => {
    if (step !== 2 || analyzePhase !== 'parsing' || !file) return undefined;
    const timer = setTimeout(() => {
      const meta = extractSkillMetaFromZipName(file.name);
      setName(meta.name);
      setDesc(meta.desc);
      setAnalyzePhase('done');
    }, 2200);
    return () => clearTimeout(timer);
  }, [step, analyzePhase, file]);

  const finishUpload = () => {
    if (!file || !name.trim() || analyzePhase !== 'done') return;
    const result = onComplete({ file, name, desc });
    if (result?.status === 'duplicate') setError('检测到相同内容，不能重复上传');
    else setStep(3);
  };

  const isAnalyzing = analyzePhase === 'scanning' || analyzePhase === 'parsing';

  return (
    <div className="fixed inset-0 z-[650] flex items-center justify-center bg-slate-900/40 backdrop-blur-md animate-in fade-in" onClick={onClose}>
      <div className="w-[620px] max-w-[calc(100vw-32px)] overflow-hidden rounded-[28px] bg-white shadow-2xl animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-slate-100 px-7 py-5">
          <div>
            <h3 className="text-xl font-extrabold text-slate-800">上传技能</h3>
            <p className="mt-1 text-[13px] font-medium text-slate-400">上传后将自动加入“我的技能”，可在工作空间对话区调用。</p>
          </div>
          <button type="button" onClick={onClose} className="rounded-xl p-2 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-700"><X size={20} /></button>
        </div>

        <div className="flex items-center gap-3 px-7 pt-5 text-[12px] font-bold">
          {[['1', '上传文件'], ['2', '完善信息'], ['3', '完成']].map(([index, label]) => (
            <React.Fragment key={index}>
              <div className={`flex items-center gap-2 ${step >= Number(index) ? 'text-blue-600' : 'text-slate-400'}`}>
                <span className={`flex h-6 w-6 items-center justify-center rounded-full text-[11px] ${step >= Number(index) ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                  {step > Number(index) ? <Check size={13} strokeWidth={3} /> : index}
                </span>
                <span>{label}</span>
              </div>
              {index !== '3' && <div className="h-px flex-1 bg-slate-100" />}
            </React.Fragment>
          ))}
        </div>

        <div className="px-7 py-6">
          {step === 1 && (
            <div className="space-y-5">
              <label className="block text-[14px] font-extrabold text-slate-800">Zip 文件 <span className="text-red-500">*</span></label>
              <input ref={fileInputRef} type="file" accept=".zip,application/zip,application/x-zip-compressed" className="hidden" onChange={e => selectFile(e.target.files?.[0])} />
              <div
                onDragOver={e => e.preventDefault()}
                onDrop={e => { e.preventDefault(); selectFile(e.dataTransfer.files?.[0]); }}
                className="flex h-14 overflow-hidden rounded-xl border border-slate-200 bg-white p-1.5"
              >
                <button type="button" onClick={() => fileInputRef.current?.click()} className="rounded-lg bg-slate-100 px-4 text-[13px] font-bold text-slate-700 transition-colors hover:bg-slate-200">选择文件</button>
                <span className={`flex min-w-0 flex-1 items-center px-3 text-[13px] font-medium ${file ? 'text-slate-700' : 'text-slate-400'}`}>
                  {file ? <span className="truncate">{file.name}</span> : '未选择任何文件'}
                </span>
                {file && <button type="button" onClick={() => setFile(null)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X size={16} /></button>}
              </div>
              {error && <p className="flex items-center gap-1.5 text-[12px] font-medium text-red-500"><AlertCircle size={14} />{error}</p>}

              <div className="rounded-2xl border border-slate-200 bg-slate-50/50 p-5">
                <div className="mb-3 flex items-center gap-2 text-[15px] font-extrabold text-slate-800"><AlertCircle size={20} className="text-slate-500" />zip 包要求</div>
                <ul className="list-disc space-y-2 pl-5 text-[13px] font-medium leading-relaxed text-slate-500 marker:text-slate-400">
                  <li>zip 中必须包含 <code className="rounded bg-white px-1.5 py-0.5 font-mono text-slate-600">SKILL.md</code></li>
                  <li><code className="rounded bg-white px-1.5 py-0.5 font-mono text-slate-600">SKILL.md</code> 只能位于压缩包顶级或次一级目录</li>
                  <li><code className="rounded bg-white px-1.5 py-0.5 font-mono text-slate-600">SKILL.md</code> 需包含 YAML 格式的技能名称（name）和描述（description）</li>
                  <li>相同内容不允许重复上传</li>
                </ul>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-5">
              <div className="rounded-xl border border-blue-100 bg-blue-50 px-4 py-3.5 text-[12px] font-medium leading-relaxed text-blue-700">
                {analyzePhase === 'done' ? (
                  <p>已完成技能文件解析，名称与简介已从 .md 中的 YAML 字段自动读取。</p>
                ) : (
                  <div key={analyzePhase} className="flex items-center gap-2 animate-in fade-in duration-300">
                    <Loader2 size={14} className="animate-spin shrink-0" strokeWidth={2.5} />
                    <span>
                      {analyzePhase === 'scanning'
                        ? '正在进行安全检测…'
                        : '正在解析技能文件，提取名称与描述…'}
                    </span>
                  </div>
                )}
              </div>

              <label className="block">
                <span className="mb-2 block text-[13px] font-bold text-slate-700">技能名称</span>
                <input
                  value={name}
                  readOnly
                  placeholder={isAnalyzing ? '解析完成后自动填入…' : '未解析到技能名称'}
                  className="w-full cursor-not-allowed rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-3 text-[13px] font-bold text-slate-500 outline-none"
                />
              </label>
              <label className="block">
                <span className="mb-2 block text-[13px] font-bold text-slate-700">技能简介</span>
                <textarea
                  value={desc}
                  readOnly
                  rows={3}
                  placeholder={isAnalyzing ? '解析完成后自动填入…' : '未解析到技能描述'}
                  className="w-full cursor-not-allowed resize-none rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-3 text-[13px] font-medium leading-relaxed text-slate-500 outline-none"
                />
              </label>
              {error && <p className="flex items-center gap-1.5 text-[12px] font-medium text-red-500"><AlertCircle size={14} />{error}</p>}
            </div>
          )}

          {step === 3 && (
            <div className="flex min-h-64 flex-col items-center justify-center text-center">
              <div className="mb-5 flex h-16 w-16 items-center justify-center rounded-3xl bg-emerald-50 text-emerald-600">
                <CheckCircle size={34} strokeWidth={2.4} />
              </div>
              <h4 className="text-xl font-extrabold text-slate-800">技能上传成功</h4>
              <p className="mt-2 max-w-sm text-[13px] font-medium leading-relaxed text-slate-400">
                「{name}」已加入我的技能，现在可以在任意工作空间的对话区选择并调用。
              </p>
            </div>
          )}
        </div>

        <div className="flex justify-between border-t border-slate-100 px-7 py-4">
          {step === 1 ? (
            <button type="button" onClick={onClose} className="rounded-xl px-4 py-2.5 text-[13px] font-bold text-slate-400 hover:bg-slate-50">取消</button>
          ) : step === 2 ? (
            <button type="button" onClick={goBackToStep1} className="rounded-xl px-4 py-2.5 text-[13px] font-bold text-slate-500 hover:bg-slate-50">上一步</button>
          ) : (
            <span />
          )}
          {step === 1 && (
            <button type="button" disabled={!file} onClick={goToStep2} className="rounded-xl bg-blue-600 px-5 py-2.5 text-[13px] font-bold text-white shadow-lg shadow-blue-200 transition-all hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-200 disabled:shadow-none">
              下一步
            </button>
          )}
          {step === 2 && (
            <button
              type="button"
              disabled={analyzePhase !== 'done' || !name.trim()}
              onClick={finishUpload}
              className="rounded-xl bg-blue-600 px-5 py-2.5 text-[13px] font-bold text-white shadow-lg shadow-blue-200 transition-all hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-200 disabled:shadow-none"
            >
              {isAnalyzing ? '检测解析中…' : '确认上传'}
            </button>
          )}
          {step === 3 && (
            <button type="button" onClick={onClose} className="rounded-xl bg-blue-600 px-5 py-2.5 text-[13px] font-bold text-white shadow-lg shadow-blue-200 hover:bg-blue-700">
              完成
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

