import { buildAnswerMarkdownFromFilteredSources } from './answerMarkdown';
import type { ReferenceSourceItem } from './mockSearchResult';

export const FILTER_BASED_TURN_PROMPT = '基于筛选结果回答';

export const INITIAL_TURN_ID = 'turn-initial';

export type ConversationTurn = {
  id: string;
  kind: 'initial' | 'follow_up';
  /** 追问时的用户问题 */
  userPrompt?: string;
  answerMarkdown: string;
  /** 该轮回答关联的参考来源 id */
  sourceIds: string[];
};

export function createInitialTurn(
  answerMarkdown: string,
  referenceSources: ReferenceSourceItem[]
): ConversationTurn {
  return {
    id: INITIAL_TURN_ID,
    kind: 'initial',
    answerMarkdown,
    sourceIds: referenceSources.map((s) => s.id),
  };
}

export function buildFollowUpAnswerMarkdown(
  question: string,
  options?: { selectedOnly?: boolean; sourceCount?: number }
): string {
  const q = question.trim();
  const scopeNote =
    options?.selectedOnly && options.sourceCount
      ? `\n\n> 本次追问仅基于您选中的 **${options.sourceCount}** 条参考来源。`
      : '';
  return `## 追问回答

针对您提出的「${q}」，结合当前检索上下文补充如下：${scopeNote}

### 要点归纳

1. 需结合已引用法规与类案，核对事实要件与程序合法性。
2. 若涉及解除劳动合同，应重点审查规章制度公示、违纪事实举证及处罚梯度是否合理。
3. 建议对照右侧本轮参考来源中的条文与案例作交叉验证。

---

*本段为演示追问回答；接入 API 后将基于本轮召回来源生成完整分析。*`;
}

/**
 * 追问轮次来源范围：
 * - 若 scopeSources 中含 userPinned，则仅使用选中来源；
 * - 否则在当前轮来源范围内按已引用条目择优。
 */
export function createFollowUpTurn(
  question: string,
  scopeSources: ReferenceSourceItem[]
): ConversationTurn {
  const pinned = scopeSources.filter((s) => s.userPinned);
  let pool: ReferenceSourceItem[];
  if (pinned.length > 0) {
    pool = pinned;
  } else {
    const cited = scopeSources.filter((s) => s.citedMark);
    pool = cited.length >= 4 ? cited : scopeSources.slice(0, 14);
  }
  return {
    id: `turn-fu-${Date.now()}`,
    kind: 'follow_up',
    userPrompt: question.trim(),
    answerMarkdown: buildFollowUpAnswerMarkdown(question, {
      selectedOnly: pinned.length > 0,
      sourceCount: pool.length,
    }),
    sourceIds: pool.map((s) => s.id),
  };
}

/** 基于当前筛选范围追加一轮回答（等同追问，来源仅限筛选结果） */
export function createFilterBasedAnswerTurn(
  query: string,
  filteredSources: ReferenceSourceItem[]
): ConversationTurn {
  return {
    id: `turn-filter-${Date.now()}`,
    kind: 'follow_up',
    userPrompt: FILTER_BASED_TURN_PROMPT,
    answerMarkdown: buildAnswerMarkdownFromFilteredSources(query, filteredSources),
    sourceIds: filteredSources.map((s) => s.id),
  };
}

export function turnSourceLabel(turn: ConversationTurn, index: number): string {
  if (turn.kind === 'initial') return '首轮回答';
  if (turn.userPrompt === FILTER_BASED_TURN_PROMPT) return '筛选回答';
  return `追问 ${index}`;
}
