/** 根据检索主题生成追问建议（演示） */
export function buildSuggestedFollowUps(query: string): string[] {
  const q = query.trim();
  if (q.includes('违纪') || q.includes('解除') || q.includes('劳动')) {
    return [
      '用人单位对同一违纪行为多次处罚是否构成违法解除？',
      '规章制度未公示时解除劳动合同有哪些法律风险？',
      '二审法院如何审查“严重违反规章制度”的认定标准？',
    ];
  }
  if (q.includes('合伙')) {
    return [
      '普通合伙与有限合伙的责任承担有何区别？',
      '合伙人退伙时财产份额如何结算？',
      '合伙协议约定竞业限制是否有效？',
    ];
  }
  return [
    '相关情形的核心法律依据有哪些？',
    '司法实践中的主要争议焦点是什么？',
    '当事人可以采取哪些维权或合规措施？',
  ];
}
