import React, { useEffect, useRef, useState } from 'react';
import {
  AlignCenter,
  AlignLeft,
  Bold,
  CheckCircle,
  ChevronLeft,
  Download,
  FileText,
  Info,
  Italic,
  List,
  ListOrdered,
  Redo,
  Underline,
  Undo,
} from 'lucide-react';
import type { SearchReportGeneratedDocument } from './searchReportExecution';
import {
  buildSearchReportDocumentSections,
  buildSearchReportDocumentTitle,
} from './searchReportDocumentContent';
import { MOCK_SAVE_KNOWLEDGE_BASES, MOCK_SAVE_WORKSPACES } from './mockSaveTargets';
import SaveTargetClickMenu, { DROPDOWN_ANCHOR_CLASS, useClickMenu } from './SaveTargetClickMenu';

export type WpsDocumentEditorPanelProps = {
  document: SearchReportGeneratedDocument;
  submittedQuery: string;
  onClose: () => void;
};

/**
 * WPS 文档在线预览/编辑区（演示壳层，后续直接替换为已有 WPS 组件）
 */
const WpsDocumentEditorPanel: React.FC<WpsDocumentEditorPanelProps> = ({
  document,
  submittedQuery,
  onClose,
}) => {
  const exportMenu = useClickMenu();
  const [toastMsg, setToastMsg] = useState('');
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const content = buildSearchReportDocumentSections(submittedQuery, document.title);
  const headerTitle = buildSearchReportDocumentTitle(document.title);

  useEffect(() => {
    return () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    };
  }, []);

  const showToast = (msg: string) => {
    setToastMsg(msg);
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    toastTimerRef.current = setTimeout(() => setToastMsg(''), 3000);
  };

  const handleExportPdf = () => {
    exportMenu.close();
  };

  const handleExportWord = () => {
    exportMenu.close();
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col bg-[#eef1f5]">
      <div className="flex h-11 shrink-0 items-center gap-2 border-b border-slate-200 bg-white px-3">
        <button
          type="button"
          onClick={onClose}
          className="inline-flex shrink-0 items-center gap-0.5 rounded-lg px-1 py-1 text-[13px] font-bold text-slate-600 transition hover:bg-slate-100 hover:text-slate-900"
        >
          <ChevronLeft size={16} strokeWidth={2.5} />
          编辑模式
        </button>
        <h2 className="min-w-0 flex-1 truncate px-2 text-center text-[13px] font-extrabold text-slate-800">
          {headerTitle}
        </h2>
        <div className="flex shrink-0 items-center gap-1">
          <div ref={exportMenu.rootRef} className="relative">
            <button
              type="button"
              onClick={exportMenu.toggle}
              aria-expanded={exportMenu.open}
              aria-haspopup="menu"
              className={`inline-flex items-center gap-1 rounded-lg px-2 py-1 text-[12px] font-bold transition ${
                exportMenu.open
                  ? 'bg-blue-50 text-blue-600'
                  : 'text-slate-600 hover:bg-slate-100 hover:text-blue-600'
              }`}
            >
              <Download size={14} strokeWidth={2.25} />
              导出
            </button>

            {exportMenu.open ? (
              <div className={DROPDOWN_ANCHOR_CLASS}>
                <div
                  role="menu"
                  className="relative min-w-[196px] animate-in fade-in zoom-in-95 rounded-xl border border-slate-200/90 bg-white py-1.5 shadow-[0_12px_32px_rgba(15,23,42,0.12)]"
                >
                  <span
                    className="absolute -top-1.5 right-4 h-3 w-3 rotate-45 border-l border-t border-slate-200/90 bg-white"
                    aria-hidden
                  />
                  <button
                    type="button"
                    role="menuitem"
                    onClick={handleExportPdf}
                    className="flex w-full items-center gap-2.5 px-3 py-2.5 text-left text-[13px] font-bold text-slate-800 transition hover:bg-slate-50"
                  >
                    <ExportPdfIcon />
                    生成 PDF 并下载
                  </button>
                  <button
                    type="button"
                    role="menuitem"
                    onClick={handleExportWord}
                    className="flex w-full items-center gap-2.5 px-3 py-2.5 text-left text-[13px] font-bold text-slate-800 transition hover:bg-slate-50"
                  >
                    <ExportWordIcon />
                    生成 Word 并下载
                  </button>
                </div>
              </div>
            ) : null}
          </div>

          <span className="mx-0.5 h-4 w-px bg-slate-200" aria-hidden />

          <SaveTargetClickMenu
            label="收录到知识库"
            items={MOCK_SAVE_KNOWLEDGE_BASES}
            confirmLabel="收录到知识库"
            onConfirm={() => showToast('收录成功')}
            buttonClassName="shrink-0 rounded-lg px-2 py-1 text-[11px] font-extrabold transition ring-1"
          />
          <SaveTargetClickMenu
            label="添加到工作空间"
            items={MOCK_SAVE_WORKSPACES}
            selectionMode="single"
            onConfirm={() => showToast('添加成功')}
            buttonClassName="shrink-0 rounded-lg px-2 py-1 text-[11px] font-extrabold transition ring-1"
          />
        </div>
      </div>

      <div className="flex h-11 shrink-0 items-center gap-1 overflow-x-auto border-b border-slate-200 bg-white px-3 shadow-sm no-scrollbar">
        <div className="mr-1 flex shrink-0 items-center gap-0.5 border-r border-slate-200 pr-2">
          <ToolbarIcon title="撤销">
            <Undo size={15} strokeWidth={2.25} />
          </ToolbarIcon>
          <ToolbarIcon title="重做">
            <Redo size={15} strokeWidth={2.25} />
          </ToolbarIcon>
        </div>
        <select
          defaultValue="h2"
          className="mr-1 shrink-0 cursor-pointer rounded-lg border-0 bg-transparent px-2 py-1.5 text-[12px] font-bold text-slate-700 outline-none hover:bg-slate-100"
        >
          <option value="body">正文</option>
          <option value="h1">一级标题</option>
          <option value="h2">二级标题</option>
          <option value="h3">三级标题</option>
        </select>
        <div className="mr-1 flex shrink-0 items-center gap-0.5 border-r border-slate-200 pr-2">
          <ToolbarIcon title="加粗" active>
            <Bold size={15} strokeWidth={2.25} />
          </ToolbarIcon>
          <ToolbarIcon title="斜体">
            <Italic size={15} strokeWidth={2.25} />
          </ToolbarIcon>
          <ToolbarIcon title="下划线">
            <Underline size={15} strokeWidth={2.25} />
          </ToolbarIcon>
        </div>
        <div className="mr-1 flex shrink-0 items-center gap-0.5 border-r border-slate-200 pr-2">
          <ToolbarIcon title="左对齐" active>
            <AlignLeft size={15} strokeWidth={2.25} />
          </ToolbarIcon>
          <ToolbarIcon title="居中对齐">
            <AlignCenter size={15} strokeWidth={2.25} />
          </ToolbarIcon>
        </div>
        <div className="flex shrink-0 items-center gap-0.5">
          <ToolbarIcon title="无序列表">
            <List size={15} strokeWidth={2.25} />
          </ToolbarIcon>
          <ToolbarIcon title="有序列表">
            <ListOrdered size={15} strokeWidth={2.25} />
          </ToolbarIcon>
        </div>
      </div>

      <div className="relative min-h-0 flex-1">
        <div className="custom-scrollbar h-full overflow-y-auto px-4 py-5 md:px-6 md:py-6">
          <div className="mx-auto w-full max-w-[720px] rounded-sm border border-slate-200/90 bg-white px-10 py-12 shadow-[0_2px_16px_rgba(15,23,42,0.08)] md:px-14 md:py-14">
            <h1 className="mb-8 text-[22px] font-extrabold leading-snug text-slate-900">
              {content.title}
            </h1>

            {content.sections.map((section) => (
              <section key={section.heading} className="mb-8 last:mb-0">
                <h2 className="mb-4 text-[16px] font-extrabold text-slate-900">{section.heading}</h2>

                {'paragraphs' in section && section.paragraphs
                  ? section.paragraphs.map((p) => (
                      <p
                        key={p.slice(0, 24)}
                        className="mb-3 text-[13px] font-medium leading-[1.85] text-slate-700 last:mb-0"
                      >
                        {p}
                      </p>
                    ))
                  : null}

                {'subsections' in section && section.subsections
                  ? section.subsections.map((sub) => (
                      <div key={sub.subheading} className="mb-5 last:mb-0">
                        <h3 className="mb-3 text-[14px] font-extrabold text-slate-800">
                          {sub.subheading}
                        </h3>
                        {sub.numbered ? (
                          <ol className="mb-3 list-decimal space-y-1.5 pl-5 text-[13px] font-medium leading-[1.85] text-slate-700">
                            {sub.numbered.map((item) => (
                              <li key={item.slice(0, 20)}>{item}</li>
                            ))}
                          </ol>
                        ) : null}
                        {sub.bullets ? (
                          <ul className="list-disc space-y-1.5 pl-5 text-[13px] font-medium leading-[1.85] text-slate-700">
                            {sub.bullets.map((item) => (
                              <li key={item.slice(0, 20)}>{item}</li>
                            ))}
                          </ul>
                        ) : null}
                      </div>
                    ))
                  : null}

                <div className="mt-6 border-t border-slate-100" />
              </section>
            ))}
          </div>
        </div>

        <button
          type="button"
          title="文档信息"
          className="absolute bottom-4 right-4 flex h-8 w-8 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-400 shadow-sm transition hover:text-slate-600"
        >
          <Info size={16} strokeWidth={2.25} />
        </button>
      </div>

      {toastMsg ? (
        <div className="pointer-events-none fixed left-1/2 top-10 z-[2000] flex -translate-x-1/2 items-center gap-2 rounded-full bg-slate-800 px-6 py-3.5 text-[13px] font-bold text-white shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          <CheckCircle size={16} className="text-emerald-400" strokeWidth={2.5} />
          {toastMsg}
        </div>
      ) : null}
    </div>
  );
};

function ExportPdfIcon() {
  return (
    <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-red-50 text-red-600 ring-1 ring-red-100">
      <FileText size={16} strokeWidth={2} />
    </div>
  );
}

function ExportWordIcon() {
  return (
    <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-blue-600 text-[11px] font-extrabold text-white shadow-sm">
      W
    </div>
  );
}

function ToolbarIcon({
  title,
  active,
  children,
}: {
  title: string;
  active?: boolean;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      title={title}
      className={`rounded-lg p-1.5 transition ${
        active ? 'bg-slate-100 text-slate-800' : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      {children}
    </button>
  );
}

export default WpsDocumentEditorPanel;
